def solve(data):
    if len(data) == 0:
        return [-1, 0]
    best_start = 0
    best_length = 1
    current_start = 0
    current_length = 1
    for index in range(1, len(data)):
        if data[index] > data[index - 1]:
            current_length = current_length + 1
        else:
            current_start = index
            current_length = 1
        if current_length > best_length:
            best_start = current_start
            best_length = current_length
    return [best_start, best_length]

