def solve(data):
    counts = {}
    left = 0
    best_start = -1
    best_length = 0
    for right in range(len(data)):
        category = data[right]
        counts[category] = counts.get(category, 0) + 1
        while len(counts) > 2:
            outgoing = data[left]
            counts[outgoing] = counts[outgoing] - 1
            if counts[outgoing] == 0:
                del counts[outgoing]
            left = left + 1
        length = right - left + 1
        if length > best_length:
            best_start = left
            best_length = length
    return [best_start, best_length]

